#nullable enable
using Marten.Events.Projections;
using HourBooking.Contracts;

namespace HourBooking.Views;

/// <summary>
/// Context: booking. Slice: my-projects. One row per (employee, project) — declared as
/// identity="employeeId, projectId" on the read model, because fields= says what a row HOLDS and
/// never what a row IS.
///
/// Registered INLINE in Program.cs: updated in the same transaction as the append, so a GWT's THEN
/// is assertable the moment the request returns.
/// </summary>
public sealed record MyProjects
{
    public string Id { get; init; } = default!;

    public Guid EmployeeId { get; init; }
    public Guid ProjectId { get; init; }
    public string ProjectName { get; init; } = default!;
    public DateTimeOffset AssignedAt { get; init; }

    /// <summary>
    /// EmployeeRemovedFromProject means DELETE THE ROW in the model's own note, but a delete supplies
    /// nothing and the completeness check reads every edge as supply — ANTI-PATTERNS.md, and blind
    /// spot 4 in OPEN-QUESTIONS.md. Kept as a flag rather than a delete so the reason a booking is
    /// refused stays visible, and so the row can say WHEN membership ended.
    /// </summary>
    public bool Left { get; init; }

    public DateOnly? LeftFrom { get; init; }

    public static string RowId(Guid employeeId, Guid projectId) => $"{employeeId}:{projectId}";
}

public sealed class MyProjectsProjection : MultiStreamProjection<MyProjects, string>
{
    public MyProjectsProjection()
    {
        Identity<EmployeeAssignedToProject>(e => MyProjects.RowId(e.EmployeeId, e.ProjectId));
        Identity<EmployeeRemovedFromProject>(e => MyProjects.RowId(e.EmployeeId, e.ProjectId));

        // ProjectCreated deliberately has NO identity rule. A project existing is not a per-employee
        // fact, so it cannot be grouped into a per-(employee, project) row. The model draws the edge
        // because the view displays projectName; the name arrives on the assignment event instead.
        // Adding a rule here would mean inventing which employee a new project belongs to.
    }

    public static MyProjects Apply(EmployeeAssignedToProject e, MyProjects current) => current with
    {
        EmployeeId = e.EmployeeId,
        ProjectId = e.ProjectId,
        ProjectName = e.ProjectName,
        AssignedAt = e.AssignedAt,
        Left = false,
        LeftFrom = null,
    };

    public static MyProjects Apply(EmployeeRemovedFromProject e, MyProjects current) => current with
    {
        EmployeeId = e.EmployeeId,
        ProjectId = e.ProjectId,
        Left = true,
        LeftFrom = e.EffectiveFrom,
    };
}
